function shuffle(a,rng){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(rng()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
function pickQuiz(rng, mode, c){
  var q,correct,pool;
  if(mode==='cap'){q='首都：'+c.n;correct=c.c;pool=COUNTRIES.map(function(x){return x.c;});}
  else if(mode==='country'){q='国家：'+c.c;correct=c.n;pool=COUNTRIES.map(function(x){return x.n;});}
  else{q=c.f+' 是哪个国家？';correct=c.n;pool=COUNTRIES.map(function(x){return x.n;});}
  var opt=[correct];
  while(opt.length<4 && opt.length<pool.length){var x=pool[Math.floor(rng()*pool.length)];if(opt.indexOf(x)<0)opt.push(x);}
  opt=shuffle(opt,rng);
  return {q:q,options:opt,answer:opt.indexOf(correct)};
}
function genSet(rng,n,mode){var used=[],out=[];for(var k=0;k<n;k++){var i;do{i=Math.floor(rng()*COUNTRIES.length);}while(used.indexOf(i)>=0&&used.length<COUNTRIES.length);used.push(i);out.push(pickQuiz(rng,mode,COUNTRIES[i]));}return out;}
